<script setup>
import {ref,onMounted} from 'vue'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
import FilePicker from '../components/FilePicker.vue'
import AttachmentList from '../components/AttachmentList.vue'
const s=useArcade(),items=ref([]),total=ref(0),page=ref(1),search=ref(''),post=ref(null),mode=ref('list'),busy=ref(false),error=ref(''),notice=ref(''),title=ref(''),content=ref(''),comment=ref(''),attachments=ref([]),attachmentBusy=ref(false),friendTarget=ref(null),friendDialog=ref(null);let key=crypto.randomUUID(),commentKey=crypto.randomUUID()
async function act(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){const data=await api('/sloud?'+new URLSearchParams({page:page.value,search:search.value}));items.value=data.items;total.value=data.total}
function list(){mode.value='list';post.value=null;act(load)}
function open(id){act(async()=>{post.value=await api('/sloud/'+id);mode.value='detail';comment.value='';commentKey=crypto.randomUUID()})}
function write(){mode.value='write';title.value='';content.value='';attachments.value=[];key=crypto.randomUUID();error.value=''}
function save(){if(attachmentBusy.value)return;act(async()=>{const result=await api('/sloud',{method:'POST',body:{title:title.value,content:content.value,attachmentIds:attachments.value.map(f=>f.id),requestKey:key}});key=crypto.randomUUID();post.value=await api('/sloud/'+result.id);mode.value='detail';notice.value='글을 공유했어요.'})}
function sendComment(){act(async()=>{await api('/sloud/'+post.value.id+'/comments',{method:'POST',body:{content:comment.value,requestKey:commentKey}});comment.value='';commentKey=crypto.randomUUID();post.value=await api('/sloud/'+post.value.id)})}
function remove(commentId){if(!window.confirm(commentId?'이 댓글을 삭제할까요?':'이 게시글을 삭제할까요?'))return;act(async()=>{await api('/sloud/'+post.value.id+(commentId?'/comments/'+commentId:''),{method:'DELETE'});if(commentId)post.value=await api('/sloud/'+post.value.id);else{mode.value='list';await load()}})}
function askFriend(c){if(s.user.role!=='student'||c.role!=='student'||c.author===s.user.id)return;friendTarget.value=c;friendDialog.value.showModal()}
function addFriend(){act(async()=>{await api('/friends',{method:'POST',body:{studentId:friendTarget.value.author}});notice.value='친구 요청을 보냈어요. 이미 받은 요청이 있다면 친구로 연결됩니다.';friendDialog.value.close();window.dispatchEvent(new Event('spokemon-friends-refresh'))})}
function turn(n){page.value=n;act(load)}
onMounted(()=>act(load))
</script>
<template><section class="sloud-page"><div class="sloud-heading"><div><p class="eyebrow">SPOKEMON COMMUNITY</p><h1>Sloud</h1><p>오늘 배운 것, 함께 나누고 싶은 내용을 공유해요.</p></div><button v-if="mode==='list'" @click="write">＋ 글쓰기</button><button v-else class="light" @click="list">목록으로</button></div><p v-if="error" class="notice" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p><section v-if="mode==='list'" class="panel"><form class="sloud-search" @submit.prevent="page=1;act(load)"><label>글 검색<input v-model="search" maxlength="100" placeholder="제목 또는 내용"/></label><button :disabled="busy">검색</button></form><div class="sloud-table"><table><thead><tr><th>제목</th><th>작성자</th><th>작성일</th></tr></thead><tbody><tr v-for="p in items" :key="p.id"><td><button class="text-button" @click="open(p.id)">{{p.title}} <b v-if="p.comments">[{{p.comments}}]</b></button></td><td>{{p.authorName}}</td><td>{{new Date(p.created_at).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'})}}</td></tr></tbody></table></div><p v-if="!items.length">첫 번째 이야기를 공유해 보세요!</p><div class="sloud-pagination"><button class="light" :disabled="busy||page<=1" @click="turn(page-1)">이전</button><span>{{page}} / {{Math.max(1,Math.ceil(total/20))}}</span><button class="light" :disabled="busy||page*20>=total" @click="turn(page+1)">다음</button></div></section><form v-else-if="mode==='write'" class="panel sloud-compose" @submit.prevent="save"><h2>새 이야기</h2><label>제목<input v-model="title" required maxlength="120"/></label><label>내용<textarea v-model="content" required maxlength="12000" rows="12" placeholder="오늘 공부한 내용이나 공유하고 싶은 이야기를 적어 주세요."/></label><FilePicker v-model="attachments" :disabled="busy" @busy="attachmentBusy=$event"/><small>텍스트·코드 파일, PDF, PNG·JPG·GIF·WEBP를 첨부할 수 있어요.</small><div class="toolbar"><button :disabled="busy||attachmentBusy||!title.trim()||!content.trim()">{{busy?'저장 중…':'공유하기'}}</button><button type="button" class="light" @click="list">취소</button></div></form><section v-else-if="post" class="panel sloud-detail"><h2>{{post.title}}</h2><p>{{post.authorName}} · {{new Date(post.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</p><p class="sloud-body">{{post.body}}</p><AttachmentList kind="sloud" :resource="post.id"/><button v-if="post.author===s.user.id||s.user.role==='admin'" class="text-button" @click="remove()">게시글 삭제</button><h3>댓글 {{post.comments.length}}</h3><p>친구가 아니어도 모든 회원이 읽고 댓글을 달 수 있어요.</p><article v-for="c in post.comments" :key="c.id" class="sloud-comment"><div><button v-if="s.user.role==='student'&&c.role==='student'&&c.author!==s.user.id" class="text-button" :aria-label="c.authorName+' 친구 추가'" @click="askFriend(c)">{{c.authorName}} ＋</button><b v-else>{{c.authorName}}</b><small>{{new Date(c.created_at).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'})}}</small><button v-if="c.author===s.user.id||s.user.role==='admin'" class="text-button" @click="remove(c.id)">삭제</button></div><p class="sloud-body">{{c.body}}</p></article><form @submit.prevent="sendComment"><label>댓글 작성<textarea v-model="comment" rows="3" maxlength="2000" required/></label><button :disabled="busy||!comment.trim()">댓글 등록</button></form></section><dialog ref="friendDialog" class="sloud-friend" aria-label="댓글 작성자 친구 추가"><h2>{{friendTarget?.authorName}}님께 친구 요청을 보낼까요?</h2><div class="toolbar"><button :disabled="busy" @click="addFriend">친구 요청</button><button class="light" :disabled="busy" @click="friendDialog.close()">취소</button></div></dialog></section></template>
<style scoped>.sloud-page{width:100%;min-width:0;margin:0 auto}.sloud-heading{display:flex;justify-content:space-between;align-items:center;gap:15px;margin:12px 0 20px}.sloud-heading h1{font-size:28px;margin:5px 0 8px}.sloud-heading p{font-size:13px}.sloud-search{display:grid;grid-template-columns:minmax(180px,420px) auto;justify-content:start;align-items:end;gap:12px}.sloud-search label{display:flex;flex-direction:column;gap:9px;min-width:0;font-size:12px}.sloud-search input{width:100%;min-width:0;box-sizing:border-box;height:42px;margin:0;padding:9px 12px}.sloud-search button{height:42px;margin:0;white-space:nowrap}.sloud-pagination{display:flex;justify-content:center;align-items:center;gap:14px;flex-wrap:wrap;margin-top:20px}.sloud-pagination button{min-height:40px;min-width:70px;margin:0}.sloud-pagination span{font-size:12px}.sloud-table{overflow:auto;margin:20px 0}.sloud-table table{width:100%;text-align:left;border-collapse:collapse}.sloud-table th,.sloud-table td{padding:14px 10px;border-bottom:1px solid var(--rpg-mid);font-size:12px}.sloud-table th{background:var(--rpg-soft)}.sloud-table td:first-child{width:65%}.sloud-table button{white-space:normal;text-align:left;font-size:14px}.sloud-compose,.sloud-detail form{display:grid;gap:14px}.sloud-compose label,.sloud-detail form label{display:flex;flex-direction:column;gap:8px}.sloud-compose textarea,.sloud-detail textarea,.sloud-compose input{width:100%;min-width:0;box-sizing:border-box}.sloud-body{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px}.sloud-comment{padding:15px 0;border-bottom:1px solid var(--rpg-mid)}.sloud-comment>div{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.sloud-comment small{font-size:10px}.sloud-friend{width:min(460px,calc(100vw - 28px));box-sizing:border-box;border:3px solid var(--rpg-edge);border-radius:14px;background:var(--rpg-paper);color:var(--rpg-ink);padding:24px}.sloud-friend::backdrop{background:#18243699}.sloud-friend h2{font-size:18px;line-height:1.8}@media(max-width:600px){.sloud-search{grid-template-columns:minmax(0,1fr) auto;width:100%;gap:10px}.sloud-heading{gap:10px}.sloud-heading>button{font-size:11px;white-space:nowrap;padding:10px 12px}.sloud-table table{min-width:0;table-layout:fixed}.sloud-table th,.sloud-table td{padding:11px 6px;font-size:10px;overflow-wrap:anywhere}.sloud-table th:first-child,.sloud-table td:first-child{width:50%}.sloud-table th:nth-child(2){width:22%}.sloud-table th:nth-child(3){width:28%}.sloud-table button{font-size:12px;overflow-wrap:anywhere}.sloud-heading h1{font-size:25px}.sloud-heading p{font-size:11px}.sloud-body{font-size:12px}}</style>
